/**
 * Pre-generated anatomical brain data for the 3D Brain.
 *
 * Shape is a smooth union (polynomial smin) of eight lobe ellipsoids —
 * left/right hemisphere, left/right frontal lobe, left/right occipital,
 * left/right temporal — plus a tapered brain stem, with a thin surface
 * noise (multi-sine field) added to the distance field for a wrinkled,
 * non-geometric surface, and a carved central fissure. Points are
 * sampled from this field (biased toward the shell), NOT scattered in a
 * bounding volume — the anatomy drives the particle placement, not the
 * other way around. Verified via width/depth profiles and ASCII
 * front/side/top silhouette previews before committing (see chat
 * history) since this can't be visually rendered in this tool.
 *
 * Colors are a cyan -> blue -> purple gradient (per the KIWI palette)
 * mixed organically by position, with per-node brightness variation and
 * rare bright-white 'hotspot' nodes.
 *
 * Connections exist in TWO forms that must stay in sync (both derived
 * from the same underlying edge set):
 *   - brainEdges3D: [nodeIndex, nodeIndex] pairs — used by EnergyLayer
 *     to random-walk across real graph adjacency.
 *   - brainConnectionSegments: pre-baked bent 3-point polylines — used
 *     by ConnectionLayer so it never needs to compute curves at runtime.
 *
 * Centered at the origin, Y-up.
 */
